parameters.jsCode:
// Quality gate: confidence = rerank + groundedness + code checks; banners, sources, Airtable row
// Mode: Run Once for All Items. Reads every node by name.

// Settings: starting values, set the final ones in calibration (10-15 test cases)
const HIGH = 75;            // 75-100 High: no banner
const MEDIUM = 40;          // 40-74 Medium, 0-39 Low
const W_RERANK = 0.3;       // weight of Cohere relevance
const W_GROUNDED = 0.7;     // weight of judge groundedness
const RERANK_SCALE = 1.0;   // e.g. 0.7 if good matches score only 0.5-0.7 (then raw / 0.7, max 1)
const INVENTED = 20;        // points off per invented item
const MISSING = 10;         // points off per missing item

const KNOWN_TOOLS = ['KAi Assist', 'Ticket Lens', 'FlowMate', 'Knowledge Finder', 'Insight Desk'];
const KNOWN_DOCS = ['KA-AI-POL-001', 'KA-AI-TOOLS-002', 'KA-BV-AI-2026', 'KA-AI-PROJ-004'];

const request = $('Normalize Request').first().json;
const agent = $('Research Agent').first().json;
const research = agent.output;
const reports = $('Write Reports A + B').first().json.output;
const judge = $('Groundedness Check').first().json.output;
const rerank = $('Cohere Rerank Score').first().json;

// 1. Scores from 0 to 1
const rawRerank = Math.max(0, ...(rerank.results || []).map(r => r.relevance_score));
const rerankScore = Math.min(1, rawRerank / RERANK_SCALE);
const groundedness = Math.min(1, Math.max(0, Number(judge.groundedness) || 0));
const base = 100 * (W_RERANK * rerankScore + W_GROUNDED * groundedness);

// 2. Code checks
const internal = research.internal_sources || [];
const external = research.external_sources || [];
const ruleList = (research.policy_rules || []).map(r => String(r).trim());
const rawResults = JSON.stringify((agent.intermediateSteps || []).map(s => s.observation));
const tool = String(research.internal_tool || 'None');

const failed = [];
if (!/^none/i.test(tool) && !KNOWN_TOOLS.some(t => tool.includes(t))) failed.push(['invented', `unknown internal tool "${tool}"`]);
if (internal.some(s => !KNOWN_DOCS.includes(s.doc_id))) failed.push(['invented', 'unknown document ID']);
if (external.some(s => !rawResults.includes(String(s.url).replace(/\/$/, '')))) failed.push(['invented', 'URL not found in the search results']);
if (ruleList.some(r => !/^(G[1-5]|A[1-7]|R[1-7])$/.test(r))) failed.push(['invented', 'invalid policy rule ID']);
if (internal.length === 0) failed.push(['missing', 'no internal source']);
if (external.length === 0) failed.push(['missing', 'no external source']);
if (ruleList.length === 0) failed.push(['missing', 'no policy rule IDs']);

const penalty = failed.reduce((sum, [kind]) => sum + (kind === 'invented' ? INVENTED : MISSING), 0);
const confidence = Math.max(0, Math.round(base - penalty));
const label = confidence >= HIGH ? 'High' : confidence >= MEDIUM ? 'Medium' : 'Low';
const lowConfidence = confidence < HIGH;
const checkNote = failed.length ? failed.map(([, msg]) => msg).join('; ') : 'all passed';

// 3. Compliance: only red goes to the AI Governance Board
const given = String(research.compliance_level || '').toLowerCase();
const level = ['green', 'amber', 'red'].includes(given) ? given : 'amber'; // when in doubt: amber
const rules = ruleList.join(', ');
const needsReview = level === 'red';

// 4. Sources list written by code, so the LLM never writes URLs
const sources = [...new Set([
  ...internal.map(s => `- ${s.doc_id} · ${s.section}`),
  ...external.map(s => `- ${s.title}: ${s.url}`),
])].join('\n');

// 5. Header and banners
const header = `# Fix My Process: ${request.reference_code}\n` +
  `**Department:** ${request.department} · **Compliance:** ${level.toUpperCase()}` +
  `${rules ? ' (' + rules + ')' : ''} · **Confidence:** ${label} (${confidence}%)`;
const banners = [];
if (level === 'red') banners.push('> **Blocked:** not allowed until the AI Governance Board approves. Use the safe alternative below.');
if (needsReview) banners.push(`> **Under review by the AI Governance Board.** See Check status with ${request.reference_code}.`);
if (label === 'Medium') banners.push(`> **Medium confidence (${confidence}%).** Check the sources before you act.`);
if (label === 'Low') banners.push(`> **Low confidence (${confidence}%).** This answer may be wrong. Check the sources before acting.`);

const reportA = [header, ...banners, reports.report_a_body, `## Sources\n${sources}`].join('\n\n');
const quality = `## Quality\nRerank ${rerankScore.toFixed(2)} · Groundedness ${groundedness.toFixed(2)} · Checks: ${checkNote}`;
const reportB = [header, reports.report_b, quality, `## Sources\n${sources}`].join('\n\n');

// 6. One Airtable row: keys must match the Submissions column names
return [{
  json: {
    reference_code: request.reference_code,
    execution_id: request.execution_id,
    created_at: request.created_at,
    channel: request.channel,
    department: request.department,
    problem: request.problem,
    current_tools: request.current_tools,
    frequency: request.frequency,
    status: needsReview ? 'Under review' : 'Completed',
    compliance_level: level,
    policy_rules: rules,
    confidence: confidence,
    confidence_label: label,
    rerank_score: Number(rerankScore.toFixed(3)),
    groundedness_score: Number(groundedness.toFixed(3)),
    low_confidence: lowConfidence,
    internal_tool: research.internal_tool,
    external_tool: research.external_tool,
    no_internal_solution: research.no_internal_solution === true,
    use_case_title: reports.use_case_title,
    executive_summary: reports.executive_summary,
    effort: reports.effort,
    impact: reports.impact,
    related_project: research.related_project,
    tool_improvement_ideas: (reports.tool_improvement_ideas || [])
      .map(i => `- ${i.idea} (confidence: ${i.confidence})`).join('\n'),
    report_a: reportA,
    report_b: reportB,
    sources: sources,
    review_status: needsReview ? 'Pending' : 'Not needed',
    duration_seconds: Math.round((Date.now() - new Date(request.created_at).getTime()) / 1000),
  },
}];

